package com.renthouse.tenancy;
import java.time.LocalDateTime;import java.util.List;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;
@Component public class ContractExpiryJob{private final JdbcTemplate j;public ContractExpiryJob(JdbcTemplate j){this.j=j;}@Scheduled(fixedDelayString="${app.jobs.contract-expiry-delay-ms:60000}")@Transactional public void expireDrafts(){List<Long> units=j.query("SELECT unit_id FROM tenancy_contract WHERE status='DRAFT' AND draft_expire_at<?",(r,n)->r.getLong(1),LocalDateTime.now());if(units.isEmpty())return;j.update("UPDATE tenancy_contract SET status='EXPIRED',updated_at=? WHERE status='DRAFT' AND draft_expire_at<?",LocalDateTime.now(),LocalDateTime.now());for(Long unit:units)j.update("UPDATE property_unit SET occupancy_status='VACANT',updated_at=? WHERE id=? AND occupancy_status='PENDING_SIGN'",LocalDateTime.now(),unit);}}
